components.css:
.ds-primary-button {
  background: var(--green);
  color: #f3f2e7;
  border: 1px solid transparent;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 12px 18px;
  font-size: 12px;
  white-space: nowrap;
}
.ds-primary-button:hover:not(:disabled) {
  background: #2b5342;
}
button, textarea {font-family: "IBM Plex Sans", sans-serif;} button {cursor: pointer; transition: background .16s, color .16s, border-color .16s;} button:disabled {opacity: .45; cursor: not-allowed;} button:focus-visible,textarea:focus-visible {outline: 3px solid #b9802c; outline-offset: 4px;}
@media (prefers-reduced-motion: reduce) {button {animation: none; transition: none;}}

.ds-text-button {
  border: 0;
  background: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 4px 0;
  font-size: 12px;
}
.ds-text-button:hover:not(:disabled) {
  color: #996421;
}
