.ds-message-columns textarea {
  width: 100%;
  height: 112px;
  background: #fcfbf7;
  border: 1px solid #d5dacf;
  border-radius: 8px;
  margin-top: 9px;
  padding: 13px 15px;
  resize: vertical;
  line-height: 1.75;
  font-family: var(--mono);
  font-size: 14px;
  letter-spacing: 0.055em;
  word-break: break-all;
  color: var(--ink);
}
