.ds-site-header nav {
  display: flex;
  align-self: stretch;
  align-items: stretch;
  margin-left: auto;
  gap: 10px;
}
.ds-site-header nav button {
  position: relative;
  border: 0;
  background: none;
  padding: 0 21px;
  color: #667166;
  font-size: 14px;
}
.ds-site-header nav button.ds-active {
  color: var(--green);
  font-weight: 600;
}
.ds-site-header nav button.ds-active:after {
  content: '';
  position: absolute;
  bottom: -1px;
  height: 3px;
  background: var(--green);
  left: 20px;
  right: 20px;
}
.ds-site-header nav button:hover {
  background: #eaece3;
}
