.ds-machine-key {
  border: 1px solid #78907b;
  width: clamp(34px, 3.8vw, 47px);
  height: clamp(34px, 3.8vw, 47px);
  border-radius: 50%;
  background: #214537;
  color: #e6ecdf;
  font-family: var(--mono);
  font-size: 18px;
  box-shadow: 0 3px 5px #091d2540;
  flex-shrink: 0;
}
.ds-machine-key:hover:not(:disabled) {
  background: #345e48;
  border-color: #c6d5bb;
}
.ds-machine-key.ds-pressed {
  border-color: #dfddbd;
  box-shadow: inset 0 2px 5px #061c1860;
}
.ds-machine-key.ds-lit {
  background: var(--amber);
  border-color: var(--amber);
  color: #183b32;
  animation: lamp-on 0.32s cubic-bezier(0.16, 1, 0.3, 1);
}
